const mcpSearchContacts = `-- name: McpSearchContacts :many
SELECT c.id, c.email, c.first_name, c.last_name, c.status, c.tier, c.created_at, c.last_open_at
FROM contacts c
WHERE c.workspace_id = $1 AND c.erased_at IS NULL
  AND (c.email ILIKE '%' || $2::text || '%' OR (c.first_name || ' ' || c.last_name) ILIKE '%' || $2::text || '%')
  AND (cardinality($3::uuid[]) = 0 OR EXISTS (
        SELECT 1 FROM list_memberships lm WHERE lm.contact_id = c.id AND lm.list_id = ANY($3::uuid[])))
ORDER BY c.email
LIMIT $4
`

type McpSearchContactsParams struct {
	WorkspaceID uuid.UUID   `json:"workspaceId"`
	Q           string      `json:"q"`
	Lists       []uuid.UUID `json:"lists"`
	Lim         int32       `json:"lim"`
}

type McpSearchContactsRow struct {
	ID         uuid.UUID  `json:"id"`
	Email      string     `json:"email"`
	FirstName  string     `json:"firstName"`
	LastName   string     `json:"lastName"`
	Status     string     `json:"status"`
	Tier       string     `json:"tier"`
	CreatedAt  time.Time  `json:"createdAt"`
	LastOpenAt *time.Time `json:"lastOpenAt"`
}

func (q *Queries) McpSearchContacts(ctx context.Context, arg McpSearchContactsParams) ([]McpSearchContactsRow, error) {
	rows, err := q.db.Query(ctx, mcpSearchContacts,
		arg.WorkspaceID,
		arg.Q,
		arg.Lists,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []McpSearchContactsRow{}
	for rows.Next() {
		var i McpSearchContactsRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.FirstName,
			&i.LastName,
			&i.Status,
			&i.Tier,
			&i.CreatedAt,
			&i.LastOpenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

